const { resolveTemplateSyncAction } = require('../theme-utils');

function makeResult(overrides = {}) {
  return {
    status: 'success',
    created: 0,
    updated: 0,
    deleted: 0,
    warnings: [],
    errors: [],
    summary: {},
    ...overrides
  };
}

async function syncPages({ config, client }) {
  const result = makeResult();
  const sourcePages = await client.source.pages.listAll();
  const destinationPages = await client.destination.pages.listAll();

  const destinationPagesByHandle = new Map(
    destinationPages.map((page) => [page.handle, page])
  );

  for (const sourcePage of sourcePages) {
    const destinationPage = destinationPagesByHandle.get(sourcePage.handle);

    try {
      const templateAction = await resolveTemplateSyncAction({
        objectType: 'page',
        templateSuffix: sourcePage.templateSuffix,
        config,
        client
      });
      result.warnings.push(...templateAction.warnings);

      if (templateAction.error) {
        throw new Error(templateAction.error);
      }

      const preparedPage = {
        ...sourcePage,
        templateSuffix: templateAction.templateSuffix
      };

      if (destinationPage) {
        if (!config.createOnly) {
          await client.destination.pages.update(destinationPage.id, preparedPage);
          result.updated += 1;
        }
      } else if (!config.updateOnly) {
        await client.destination.pages.create(preparedPage);
        result.created += 1;
      }
    } catch (error) {
      result.errors.push(`Error processing "${sourcePage.title}": ${error.message}`);
    }
  }

  if (config.cleanDestination && !config.createOnly && !config.updateOnly) {
    const sourceHandles = new Set(sourcePages.map((page) => page.handle));

    for (const destinationPage of destinationPages) {
      if (sourceHandles.has(destinationPage.handle)) {
        continue;
      }

      try {
        await client.destination.pages.delete(destinationPage.id);
        result.deleted += 1;
      } catch (error) {
        result.errors.push(
          `Error deleting "${destinationPage.title}": ${error.message}`
        );
      }
    }
  }

  result.status = result.errors.length > 0 ? 'failed' : 'success';
  result.summary = {
    sourceCount: sourcePages.length,
    destinationCount: destinationPages.length
  };

  return result;
}

module.exports = {
  syncPages
};
